package org.circus.core;
import java.io.*;import java.nio.file.*;import java.util.*;
/** Eight original alarm scripts, with original selection and inline save/load. */
public final class Dc2BorrowedAudit {
 private static int checks;private static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
 private static Dc2Session session(CircusResources d,TextCodec codec)throws IOException{return new Dc2Session(d,codec,h->((PcHost)h).dc2LocalHour=()->20);}
 private static void run(Dc2Session s)throws IOException{for(int n=0;n<10000;n++){MesVm.Status status=s.vm.run(1);if(status==MesVm.Status.FAULT)throw new IOException(s.vm.error());if(s.host.saveRequest>=0||s.host.loadRequest>=0||s.host.ui.waiting)return;if(status==MesVm.Status.WAIT_HOST){s.vm.elapse(40);for(int ch=0;ch<6;ch++)s.host.audioCompleted(ch,s.host.audioGeneration[ch]);s.vm.signalHost(s.host.waitTicket(),MesVm.HostSignal.MEDIA_COMPLETE);if(s.host.remainingMillis()>0)s.vm.elapse(600000);else{s.vm.signalHost(s.host.waitTicket(),MesVm.HostSignal.TEXT_COMPLETE);s.vm.signalHost(s.host.waitTicket(),MesVm.HostSignal.ADVANCE);}}}throw new IOException("Alarm audit instruction budget "+s.vm.scriptName()+"@"+Integer.toHexString(s.vm.offset())+" status="+s.vm.status()+" audio="+s.host.audioMask+" remain="+s.host.remainingMillis());}
 private static void choose(Dc2Session s,String label)throws IOException{for(int n=0;n<s.host.ui.buttons.size();n++)if(s.host.ui.buttons.get(n).action.equals(label)){check(s.vm.activateMenu(s.host.waitTicket(),n),"actual alarm label "+label);return;}throw new IOException("Alarm label missing "+label);}
 public static void main(String[] args)throws Exception{
  if(args.length!=2)throw new IOException("Require readonly_DC2_GAME owned_OUTPUT");Path game=Paths.get(args[0]).toRealPath(),out=DesktopRouteAudit.outputOutsideGame(game,args[1]);CircusResources d=new CircusResources(new GameResources(new LocalGameStorage(game),"dc2.exe"),Profiles.get("dc2-3363"));TextCodec codec=GameText.detect(d.files,d.profile);List<Object> results=new ArrayList<>();
  for(String type:new String[]{"nin","obk"})for(int day=20;day<=23;day++){
   String name="meza_"+type+"_"+day;
   for(String label:new String[]{"fast","normal","slow"}){
    Dc2Session s=session(d,codec);s.vm.enterSystem(name);run(s);check(s.host.ui.waiting&&s.vm.scriptName().equals(name),"real alarm initializes50 and original three-button menu");check(((PcHost)s.host).dc2Borrowed.continuation()==0x88,"actual50 caller PC follows head");byte[] snapshot=s.snapshot();Dc2Session copy=session(d,codec);copy.host.copyPersistentFrom(s.host);copy.restore(snapshot);check(Arrays.equals(snapshot,copy.snapshot()),"original alarm active+borrowed session byte roundtrip");choose(s,label);for(int n=0;n<100&&s.vm.scriptName().equals(name);n++){if(s.vm.run(1)==MesVm.Status.FAULT)throw new IOException(s.vm.error());if(!s.vm.scriptName().equals(name))break;}check(!s.vm.scriptName().equals(name),"original "+label+" transfers to next story");results.add(Json.obj("script",name,"choice",label,"story",s.vm.scriptName()));
   }
   Dc2Session s=session(d,codec);s.vm.enterSystem(name);run(s);check(s.vm.activateMenu(s.host.waitTicket(),-1),"alarm right enters its original inline menu");run(s);choose(s,"save");run(s);check(s.host.gridWaiting,"original inline save page");check(s.vm.activateGrid(s.host.waitTicket(),2),"original native slot2 selection");run(s);if(s.host.saveRequest<0){choose(s,"iconset00");run(s);}if(s.host.saveRequest<0){choose(s,"dosave_s");run(s);}check(s.host.saveRequest==2,"original alarm requests selected slot2");byte[] slot=s.dc2BorrowedSnapshot(new Dc2BorrowedState.SaveMetadata(2026,11,7,20,1));Dc2Session loaded=session(d,codec);loaded.restore(slot);check(loaded.vm.scriptName().equals(name)&&loaded.vm.offset()==0x88&&loaded.host.saveRequest<0,"saved slot restores50 caller, never inline SAVE program counter");check(loaded.vm.variables.read(8,25)==0,"50 saved ordinary before menu sets already-open flag");run(loaded);check(loaded.host.ui.waiting&&loaded.host.audio[0].equals(s.host.audio[0]),"loaded producer rebuilds actual alarm UI and music request");
   loaded.host.availableSaves.add(2);check(loaded.vm.activateMenu(loaded.host.waitTicket(),-1),"loaded alarm reenters its original inline menu");run(loaded);choose(loaded,"load");run(loaded);check(loaded.host.gridWaiting&&loaded.vm.activateGrid(loaded.host.waitTicket(),2),"original Load grid selects available2");run(loaded);choose(loaded,"doload");run(loaded);check(loaded.host.loadRequest==2,"original alarm Load requests the selected slot");loaded.restore(slot);check(loaded.host.loadRequest<0&&loaded.vm.offset()==0x88,"read slot replaces the Load menu with the saved50 continuation");
   byte[] active=s.snapshot();Dc2Session pending=session(d,codec);pending.host.copyPersistentFrom(s.host);pending.restore(active);check(pending.host.saveRequest==2&&Arrays.equals(active,pending.snapshot()),"mid-SAVE session retains active UI and independent borrowed caller");
  }
  Files.write(out.resolve("result.json"),(Json.text(Json.obj("pass",true,"checks",checks,"selections",results,"scripts",8,"original_exe_executed",false,"original_game_directory_written",false,"scope","actual original alarm MES choices, selected save continuation and active session persistence; portable context, not Windows8004 equivalence"))+"\n").getBytes("UTF-8"));System.out.println("Dc2BorrowedAudit "+checks+" PASS;8 actual alarm scripts");
 }
}
